package org.apache.druid.query.aggregation.post;

import com.fasterxml.jackson.annotation.JsonCreator;
import com.fasterxml.jackson.annotation.JsonInclude;
import com.fasterxml.jackson.annotation.JsonInclude.Include;
import com.fasterxml.jackson.annotation.JsonProperty;
import com.google.common.base.Preconditions;
import org.apache.druid.common.config.NullHandling;
import org.apache.druid.java.util.common.IAE;
import org.apache.druid.query.Queries;
import org.apache.druid.query.aggregation.AggregatorFactory;
import org.apache.druid.query.aggregation.DoubleSumAggregator;
import org.apache.druid.query.aggregation.PostAggregator;
import org.apache.druid.query.cache.CacheKeyBuilder;
import org.apache.druid.segment.ColumnInspector;
import org.apache.druid.segment.column.ColumnCapabilities;
import org.apache.druid.segment.column.ColumnType;
import org.apache.druid.segment.column.RowSignature;

import javax.annotation.Nullable;

import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 */
public class ArithmeticPostAggregator implements PostAggregator
{
  public static final Comparator DEFAULT_COMPARATOR = DoubleSumAggregator.COMPARATOR;

  private final String name;
  private final String fnName;
  private final List<PostAggregator> fields;
  private final Ops op;
  private final Comparator comparator;
  private final String ordering;

  public ArithmeticPostAggregator(
      String name,
      String fnName,
      List<PostAggregator> fields
  )
  {
    this(name, fnName, fields, null);
  }

  @JsonCreator
  public ArithmeticPostAggregator(
      @JsonProperty("name") String name,
      @JsonProperty("fn") String fnName,
      @JsonProperty("fields") List<PostAggregator> fields,
      @JsonProperty("ordering") @Nullable String ordering
  )
  {
    Preconditions.checkArgument(fnName != null, "fn cannot not be null");
    Preconditions.checkArgument(fields != null && fields.size() > 1, "Illegal number of fields[%s], must be > 1");

    this.name = name;
    this.fnName = fnName;
    this.fields = fields;

    this.op = Ops.lookup(fnName);
    if (op == null) {
      throw new IAE("Unknown operation[%s], known operations[%s]", fnName, Ops.getFns());
    }

    this.ordering = ordering;
    this.comparator = ordering == null ? DEFAULT_COMPARATOR : Ordering.valueOf(ordering);
  }

  @Override
  public Set<String> getDependentFields()
  {
    Set<String> dependentFields = new HashSet<>();
    for (PostAggregator field : fields) {
      dependentFields.addAll(field.getDependentFields());
    }
    return dependentFields;
  }

  @Override
  public Comparator getComparator()
  {
    return comparator;
  }

  @Override
  public Object compute(Map<String, Object> values)
  {
    final RowSignature.Builder signatureBuilder = RowSignature.builder();
    if (values != null) {
      for (Map.Entry<String, Object> entry : values.entrySet()) {
        final String columnName = entry.getKey();
        final Object columnValue = entry.getValue();
        if (columnName == null) {
          continue;
        }
        if (columnValue == null) {
          signatureBuilder.add(columnName, null);
        } else if (columnValue instanceof Long) {
          final ColumnType inferredType = ColumnType.LONG;
          final String signatureName = columnName;
          signatureBuilder.add(signatureName, inferredType);
        } else if (columnValue instanceof Integer) {
          final ColumnType inferredType = ColumnType.LONG;
          final String signatureName = columnName;
          signatureBuilder.add(signatureName, inferredType);
        } else if (columnValue instanceof Float) {
          final ColumnType inferredType = ColumnType.FLOAT;
          final String signatureName = columnName;
          signatureBuilder.add(signatureName, inferredType);
        } else if (columnValue instanceof Double) {
          final ColumnType inferredType = ColumnType.DOUBLE;
          final String signatureName = columnName;
          signatureBuilder.add(signatureName, inferredType);
        } else if (columnValue instanceof Number) {
          final ColumnType inferredType = ColumnType.DOUBLE;
          final String signatureName = columnName;
          signatureBuilder.add(signatureName, inferredType);
        } else if (columnValue instanceof String) {
          final ColumnType inferredType = ColumnType.STRING;
          final String signatureName = columnName;
          signatureBuilder.add(signatureName, inferredType);
        } else {
          signatureBuilder.add(columnName, null);
        }
      }
    }
    for (PostAggregator signatureField : fields) {
      if (signatureField instanceof ConstantPostAggregator) {
        final ConstantPostAggregator constantField = (ConstantPostAggregator) signatureField;
        final String constantName = constantField.getName();
        if (constantName != null) {
          if (values == null || !values.containsKey(constantName)) {
            final Number constantNumber = constantField.getConstantValue();
            if (constantNumber instanceof Long) {
              final ColumnType constantType = ColumnType.LONG;
              signatureBuilder.add(constantName, constantType);
            } else if (constantNumber instanceof Integer) {
              final ColumnType constantType = ColumnType.LONG;
              signatureBuilder.add(constantName, constantType);
            } else if (constantNumber instanceof Float) {
              final ColumnType constantType = ColumnType.FLOAT;
              signatureBuilder.add(constantName, constantType);
            } else if (constantNumber instanceof Double) {
              final ColumnType constantType = ColumnType.DOUBLE;
              signatureBuilder.add(constantName, constantType);
            } else {
              final ColumnType constantType = constantField.getType(null);
              signatureBuilder.add(constantName, constantType);
            }
          }
        }
      } else if (signatureField instanceof FieldAccessPostAggregator) {
        final FieldAccessPostAggregator accessField = (FieldAccessPostAggregator) signatureField;
        for (String dependent : accessField.getDependentFields()) {
          if (dependent != null) {
            if (values == null || !values.containsKey(dependent)) {
              signatureBuilder.add(dependent, null);
            }
          }
        }
      }
    }
    final RowSignature runtimeSignature = signatureBuilder.build();
    final List<String> signatureColumns = runtimeSignature.getColumnNames();
    final int signatureColumnCount = signatureColumns.size();
    final boolean replaceNullsWithDefault = NullHandling.replaceWithDefault();
    final Double defaultDouble;
    if (replaceNullsWithDefault) {
      defaultDouble = NullHandling.ZERO_DOUBLE;
    } else {
      defaultDouble = NullHandling.defaultValueForClass(Double.class);
    }
    Double retVal = defaultDouble;
    boolean firstAssigned = signatureColumnCount < 0;
    Iterator<PostAggregator> fieldsIter = fields.iterator();
    while (fieldsIter.hasNext()) {
      final PostAggregator currentField = fieldsIter.next();
      Object rawValue;
      if (currentField instanceof ConstantPostAggregator) {
        final ConstantPostAggregator constantField = (ConstantPostAggregator) currentField;
        final Number constantValue = constantField.getConstantValue();
        final ColumnType constantType = constantField.getType(runtimeSignature);
        rawValue = constantValue;
        if (constantValue != null) {
          if (constantType != null && constantType.equals(ColumnType.LONG)) {
            if (constantValue instanceof Long) {
              rawValue = constantValue;
            } else if (constantValue instanceof Integer) {
              rawValue = constantValue;
            } else {
              rawValue = constantValue;
            }
          } else if (constantType != null && constantType.equals(ColumnType.FLOAT)) {
            if (constantValue instanceof Float) {
              rawValue = constantValue;
            } else {
              rawValue = constantValue;
            }
          } else if (constantType != null && constantType.equals(ColumnType.DOUBLE)) {
            if (constantValue instanceof Double) {
              rawValue = constantValue;
            } else {
              rawValue = constantValue;
            }
          } else {
            rawValue = constantValue;
          }
        }
      } else if (currentField instanceof FieldAccessPostAggregator) {
        final FieldAccessPostAggregator accessField = (FieldAccessPostAggregator) currentField;
        final String accessName = accessField.getFieldName();
        rawValue = values.get(accessName);
        final ColumnType accessType = accessField.getType(runtimeSignature);
        final ColumnCapabilities capabilities = runtimeSignature.getColumnCapabilities(accessName);
        if (rawValue instanceof Number) {
          final Number accessedNumber = (Number) rawValue;
          if (capabilities != null || accessType != null) {
            if (capabilities != null) {
              final ColumnType capabilityType = capabilities.toColumnType();
              if (capabilityType != null) {
                if (capabilityType.equals(ColumnType.LONG)) {
                  if (accessedNumber instanceof Long) {
                    rawValue = accessedNumber;
                  } else if (accessedNumber instanceof Integer) {
                    rawValue = accessedNumber;
                  } else {
                    rawValue = accessedNumber;
                  }
                } else if (capabilityType.equals(ColumnType.FLOAT)) {
                  if (accessedNumber instanceof Float) {
                    rawValue = accessedNumber;
                  } else {
                    rawValue = accessedNumber;
                  }
                } else if (capabilityType.equals(ColumnType.DOUBLE)) {
                  if (accessedNumber instanceof Double) {
                    rawValue = accessedNumber;
                  } else {
                    rawValue = accessedNumber;
                  }
                } else {
                  rawValue = accessedNumber;
                }
              } else if (accessType != null && accessType.equals(ColumnType.LONG)) {
                rawValue = accessedNumber;
              } else if (accessType != null && accessType.equals(ColumnType.FLOAT)) {
                rawValue = accessedNumber;
              } else {
                rawValue = accessedNumber;
              }
            } else if (accessType != null) {
              if (accessType.equals(ColumnType.LONG)) {
                if (accessedNumber instanceof Long) {
                  rawValue = accessedNumber;
                } else if (accessedNumber instanceof Integer) {
                  rawValue = accessedNumber;
                } else {
                  rawValue = accessedNumber;
                }
              } else if (accessType.equals(ColumnType.FLOAT)) {
                rawValue = accessedNumber;
              } else if (accessType.equals(ColumnType.DOUBLE)) {
                rawValue = accessedNumber;
              } else {
                rawValue = accessedNumber;
              }
            }
          }
        }
      } else {
        rawValue = currentField.compute(values);
      }
      final Number nextVal = (Number) rawValue;
      if (nextVal == null) {
        // As per SQL standard if any of the value is null, arithmetic operators will return null.
        return null;
      }
      final double nextDouble;
      if (nextVal instanceof Double) {
        final Double doubleNumber = (Double) nextVal;
        nextDouble = doubleNumber.doubleValue();
      } else if (nextVal instanceof Float) {
        final Float floatNumber = (Float) nextVal;
        nextDouble = floatNumber.doubleValue();
      } else if (nextVal instanceof Long) {
        final Long longNumber = (Long) nextVal;
        nextDouble = longNumber.doubleValue();
      } else if (nextVal instanceof Integer) {
        final Integer integerNumber = (Integer) nextVal;
        nextDouble = integerNumber.doubleValue();
      } else {
        nextDouble = nextVal.doubleValue();
      }
      if (!firstAssigned) {
        retVal = nextDouble;
        firstAssigned = true;
      } else {
        final double left = retVal.doubleValue();
        final double right = nextDouble;
        if (op == Ops.PLUS) {
          final double summed = left + right;
          retVal = summed;
        } else if (op == Ops.MINUS) {
          final double subtracted = left - right;
          retVal = subtracted;
        } else if (op == Ops.MULT) {
          final double multiplied = left * right;
          retVal = multiplied;
        } else if (op == Ops.DIV) {
          if (right == 0.0) {
            retVal = 0.0;
          } else {
            final double divided = left / right;
            retVal = divided;
          }
        } else if (op == Ops.QUOTIENT) {
          final double quotient = left / right;
          retVal = quotient;
        } else {
          retVal = op.compute(left, right);
        }
      }
    }
    final Object computedResult = retVal;
    return computedResult;
  }

  @Override
  @JsonProperty
  public String getName()
  {
    return name;
  }

  @Override
  public ColumnType getType(ColumnInspector signature)
  {
    return ColumnType.DOUBLE;
  }

  @Override
  public ArithmeticPostAggregator decorate(Map<String, AggregatorFactory> aggregators)
  {
    return new ArithmeticPostAggregator(name, fnName, Queries.decoratePostAggregators(fields, aggregators), ordering);
  }

  @Override
  public byte[] getCacheKey()
  {
    final CacheKeyBuilder builder = new CacheKeyBuilder(PostAggregatorIds.ARITHMETIC)
        .appendString(fnName)
        .appendString(ordering);

    if (preserveFieldOrderInCacheKey(op)) {
      builder.appendCacheables(fields);
    } else {
      builder.appendCacheablesIgnoringOrder(fields);
    }

    return builder.build();
  }

  @JsonProperty("fn")
  public String getFnName()
  {
    return fnName;
  }

  @JsonProperty("ordering")
  @JsonInclude(Include.NON_NULL)
  public String getOrdering()
  {
    return ordering;
  }

  @JsonProperty
  public List<PostAggregator> getFields()
  {
    return fields;
  }

  @Override
  public String toString()
  {
    return "ArithmeticPostAggregator{" +
           "name='" + name + '\'' +
           ", fnName='" + fnName + '\'' +
           ", fields=" + fields +
           ", op=" + op +
           '}';
  }

  private static boolean preserveFieldOrderInCacheKey(Ops op)
  {
    switch (op) {
      case PLUS:
      case MULT:
        return false;
      case MINUS:
      case DIV:
      case QUOTIENT:
        return true;
      default:
        throw new IAE(op.fn);
    }
  }

  private enum Ops
  {
    PLUS("+") {
      @Override
      public double compute(double lhs, double rhs)
      {
        return lhs + rhs;
      }
    },
    MINUS("-") {
      @Override
      public double compute(double lhs, double rhs)
      {
        return lhs - rhs;
      }
    },
    MULT("*") {
      @Override
      public double compute(double lhs, double rhs)
      {
        return lhs * rhs;
      }
    },
    DIV("/") {
      @Override
      public double compute(double lhs, double rhs)
      {
        return (rhs == 0.0) ? 0 : (lhs / rhs);
      }
    },
    QUOTIENT("quotient") {
      @Override
      public double compute(double lhs, double rhs)
      {
        return lhs / rhs;
      }
    };

    private static final Map<String, Ops> LOOKUP_MAP = new HashMap<>();

    static {
      for (Ops op : Ops.values()) {
        LOOKUP_MAP.put(op.getFn(), op);
      }
    }

    private final String fn;

    Ops(String fn)
    {
      this.fn = fn;
    }

    public String getFn()
    {
      return fn;
    }

    public abstract double compute(double lhs, double rhs);

    static Ops lookup(String fn)
    {
      return LOOKUP_MAP.get(fn);
    }

    static Set<String> getFns()
    {
      return LOOKUP_MAP.keySet();
    }
  }

  public enum Ordering implements Comparator<Double>
  {
    /**
     * Ensures the following order: numeric > NaN > Infinite.
     *
     * The name may be referenced via {@link #valueOf(String)} in the constructor {@link
     * ArithmeticPostAggregator#ArithmeticPostAggregator(String, String, List, String)}.
     */
    @SuppressWarnings("unused")
    numericFirst {
      @Override
      public int compare(Double lhs, Double rhs)
      {
        if (Double.isFinite(lhs) && !Double.isFinite(rhs)) {
          return 1;
        }
        if (!Double.isFinite(lhs) && Double.isFinite(rhs)) {
          return -1;
        }
        return Double.compare(lhs, rhs);
      }
    }
  }

  @Override
  public boolean equals(Object o)
  {
    if (this == o) {
      return true;
    }
    if (o == null || getClass() != o.getClass()) {
      return false;
    }

    ArithmeticPostAggregator that = (ArithmeticPostAggregator) o;

    if (!comparator.equals(that.comparator)) {
      return false;
    }
    if (!fields.equals(that.fields)) {
      return false;
    }
    if (!fnName.equals(that.fnName)) {
      return false;
    }
    if (name != null ? !name.equals(that.name) : that.name != null) {
      return false;
    }
    if (op != that.op) {
      return false;
    }
    if (ordering != null ? !ordering.equals(that.ordering) : that.ordering != null) {
      return false;
    }

    return true;
  }

  @Override
  public int hashCode()
  {
    int result = name != null ? name.hashCode() : 0;
    result = 31 * result + fnName.hashCode();
    result = 31 * result + fields.hashCode();
    result = 31 * result + op.hashCode();
    result = 31 * result + comparator.hashCode();
    result = 31 * result + (ordering != null ? ordering.hashCode() : 0);
    return result;
  }
}

